// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(uint256 id, address to, address attacker) public {
        // The id space is entirely un-minted: c has no public minting surface, so
        // _ownerOf[id] is address(0) for every fuzzed id.
        vm.assume(to != address(0));

        // Attacker passes from == msg.sender (attacker) so the NOT_AUTHORIZED
        // check passes; only the WRONG_FROM check should block the transfer.
        vm.prank(attacker);
        bool ok;
        try c.transferFrom(attacker, to, id) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: transferFrom on a never-minted token id must always revert
        // (the token has no owner, so from == _ownerOf[id] can never hold).
        assertTrue(!ok);
    }
}
